<?php
if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__ . '/../koneksi.php';
if (empty($_SESSION['username'])) { header('Location: ../login.php'); exit; }
function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$username = $_SESSION['username'];
$gambarAdmin = 'default.png';
$stmtAdmin = $conn->prepare('SELECT gambar FROM admin WHERE username = ? LIMIT 1');
if ($stmtAdmin) { $stmtAdmin->bind_param('s', $username); $stmtAdmin->execute(); $admin = $stmtAdmin->get_result()->fetch_assoc(); if (!empty($admin['gambar'])) $gambarAdmin = $admin['gambar']; $stmtAdmin->close(); }
$cartItemCount = isset($_SESSION['cart']) && is_array($_SESSION['cart']) ? count($_SESSION['cart']) : 0;

$flash = $_SESSION['flash_produk'] ?? ''; unset($_SESSION['flash_produk']);
$search = trim($_GET['search'] ?? ''); $page = max(1,(int)($_GET['halaman'] ?? 1)); $limit=8;
if ($search !== '') { $like='%'.$search.'%'; $count=$conn->prepare('SELECT COUNT(*) jumlah FROM produk p LEFT JOIN kategori k ON p.id_kategori=k.id_kategori WHERE p.nama_produk LIKE ? OR k.nama_kategori LIKE ?'); $count->bind_param('ss',$like,$like); }
else { $count=$conn->prepare('SELECT COUNT(*) jumlah FROM produk'); }
$count->execute(); $total=(int)$count->get_result()->fetch_assoc()['jumlah']; $count->close(); $pages=max(1,(int)ceil($total/$limit)); $page=min($page,$pages); $offset=($page-1)*$limit;
if ($search !== '') { $stmt=$conn->prepare('SELECT p.id_produk,p.id_kategori,p.nama_produk,p.harga,p.stok,p.foto,k.nama_kategori FROM produk p LEFT JOIN kategori k ON p.id_kategori=k.id_kategori WHERE p.nama_produk LIKE ? OR k.nama_kategori LIKE ? ORDER BY p.id_produk DESC LIMIT ? OFFSET ?'); $stmt->bind_param('ssii',$like,$like,$limit,$offset); }
else { $stmt=$conn->prepare('SELECT p.id_produk,p.id_kategori,p.nama_produk,p.harga,p.stok,p.foto,k.nama_kategori FROM produk p LEFT JOIN kategori k ON p.id_kategori=k.id_kategori ORDER BY p.id_produk DESC LIMIT ? OFFSET ?'); $stmt->bind_param('ii',$limit,$offset); }
$stmt->execute(); $products=$stmt->get_result();
?>
