<ul class="pagination"><li><a href="?halaman=<?= max(1,$page-1) ?>&search=<?= urlencode($search) ?>">&laquo;</a></li><?php for($i=1;$i<=$pages;$i++): ?><li><a class="<?= $i===$page?'active':'' ?>" href="?halaman=<?= $i ?>&search=<?= urlencode($search) ?>"><?= $i ?></a></li><?php endfor; ?><li><a href="?halaman=<?= min($pages,$page+1) ?>&search=<?= urlencode($search) ?>">&raquo;</a></li></ul>
<?php else: ?><div class="empty"><i class="fas fa-box-open fa-3x" style="color:#1d4ed8"></i><h3><?= $search!==''?'Produk tidak ditemukan':'Belum ada produk' ?></h3><p><?= $search!==''?'Tidak ada produk yang cocok dengan pencarian.':'Tambahkan produk untuk mulai mengelola inventaris kasir.' ?></p><a class="btn primary" href="tambah1.php"><i class="fas fa-plus"></i> Tambah Produk</a></div><?php endif; ?></main><a class="cart" href="../checkout/pesanan_pembeli.php" aria-label="Buka keranjang"><i class="fas fa-shopping-cart"></i><?php if($cartItemCount>0): ?><sup><?= $cartItemCount ?></sup><?php endif; ?></a></div></body></html>